int main(void) {
    int n = 27;
    int step = 0;
    while (n != 1 && step < 12) {
        if (n % 2 == 0) {
            n = n / 2;
        } else {
            n = 3 * n + 1;
        }
        step++;
    }
    printf("%d %d\n", step, n);
    return 0;
}

